-- Speaking library v2: multi-level items, student-safe presenter content, and reusable seed catalogue.

alter table public.admin_speaking_activities
  add column if not exists student_intro text,
  add column if not exists student_steps jsonb not null default '[]'::jsonb,
  add column if not exists useful_language jsonb not null default '[]'::jsonb,
  add column if not exists presenter_style text not null default 'prompt';

alter table public.admin_speaking_activities
  drop constraint if exists admin_speaking_activities_student_steps_array,
  drop constraint if exists admin_speaking_activities_useful_language_array,
  drop constraint if exists admin_speaking_activities_presenter_style_check;

alter table public.admin_speaking_activities
  add constraint admin_speaking_activities_student_steps_array check (jsonb_typeof(student_steps) = 'array'),
  add constraint admin_speaking_activities_useful_language_array check (jsonb_typeof(useful_language) = 'array'),
  add constraint admin_speaking_activities_presenter_style_check
    check (presenter_style in ('prompt','choice','odd_one_out','repair','taboo','story','ranking','roleplay'));

update public.admin_speaking_activities activity
set prompts = (
  select coalesce(
    jsonb_agg(
      case
        when jsonb_typeof(entry.value) = 'string' then jsonb_build_object(
          'text', entry.value #>> '{}',
          'levels', to_jsonb(activity.levels),
          'student_support', '',
          'challenge', '',
          'teacher_note', ''
        )
        else entry.value
      end
      order by entry.ordinality
    ),
    '[]'::jsonb
  )
  from jsonb_array_elements(activity.prompts) with ordinality entry(value, ordinality)
)
where exists (
  select 1
  from jsonb_array_elements(activity.prompts) entry(value)
  where jsonb_typeof(entry.value) = 'string'
);

create temporary table speaking_activity_seed(payload jsonb);
insert into speaking_activity_seed(payload) values ('[{"tags":["conversation","critical thinking"],"goals":["opinions","nuance","extended answers"],"title":"Agree, Disagree, It Depends","levels":["A2","B1","B2","C1"],"status":"active","prompts":[{"text":"People should never work during their holidays.","levels":["A2","B1"],"challenge":"Give one exception to your position.","teacher_note":"Push beyond yes/no: require because + example.","student_support":"Think about rest, emergencies and different jobs."},{"text":"Being good at your job is more important than enjoying it.","levels":["B1","B2","C1"],"challenge":"Now argue the opposite side for 30 seconds.","teacher_note":"Good for hedging: to some extent, in the long run.","student_support":"Think about motivation, salary and long-term satisfaction."},{"text":"Social media makes friendships weaker.","levels":["A2","B1","B2"],"challenge":"Name one situation where the opposite is true.","teacher_note":"","student_support":"Think about distance, attention and communication."},{"text":"A four-day working week would improve most companies.","levels":["B2","C1"],"challenge":"What kind of company might struggle with it?","teacher_note":"Useful for qualifiers and exceptions.","student_support":"Think about productivity, customers and workload."}],"summary":"Opinion prompts where “it depends” only counts if the learner explains exactly what it depends on.","favorite":false,"variants":["Fast version: 45 seconds per statement.","No neutral answer: ban “it depends” for one round.","C1: require one counterargument before concluding."],"group_size":"1–6","instructions":"Show one statement. The learner chooses Agree, Disagree or It depends, then supports the choice with reasons and examples.","activity_type":"conversation","student_intro":"Choose Agree, Disagree or It depends — then make your position convincing.","student_steps":["Choose your position.","Give a reason.","Add an example.","Respond to the challenge."],"teacher_notes":null,"presenter_style":"choice","useful_language":["I tend to agree because…","I’m not completely convinced that…","It depends on…","One exception would be…"],"duration_minutes":15},{"tags":["fun","creative"],"goals":["fluency","modals","advice"],"title":"Bad Advice Only","levels":["A2","B1","B2"],"status":"active","prompts":[{"text":"I have an important interview tomorrow and I haven’t prepared.","levels":["A2","B1","B2"],"challenge":"","teacher_note":"","student_support":""},{"text":"My colleague keeps interrupting me in meetings.","levels":["A2","B1","B2"],"challenge":"","teacher_note":"","student_support":""},{"text":"I’m always late because I snooze my alarm five times.","levels":["A2","B1","B2"],"challenge":"","teacher_note":"","student_support":""},{"text":"I need to improve my English but I hate studying grammar books.","levels":["A2","B1","B2"],"challenge":"","teacher_note":"","student_support":""},{"text":"I accidentally sent a private message to the wrong person.","levels":["A2","B1","B2"],"challenge":"","teacher_note":"","student_support":""}],"summary":"Lo studente deve dare intenzionalmente il peggior consiglio possibile, poi correggerlo con una soluzione reale.","favorite":true,"variants":["B1+: obbliga a usare should / shouldn’t / if I were you.","Business version: solo problemi di lavoro.","Follow-up: tu difendi il cattivo consiglio e lo studente deve convincerti."],"group_size":"1–5","instructions":"Presenta un problema. Prima lo studente dà un consiglio assurdo o pessimo. Poi deve spiegare perché sarebbe una cattiva idea e proporre un consiglio vero.","activity_type":"speaking_game","student_intro":null,"student_steps":[],"teacher_notes":null,"presenter_style":"prompt","useful_language":[],"duration_minutes":12},{"tags":["warm-up","low prep"],"goals":["fluency","follow-up questions","confidence"],"title":"Conversation Roulette","levels":["A2","B1","B2"],"status":"active","prompts":[{"text":"What is something you used to dislike but now enjoy?","levels":["A2","B1","B2"],"challenge":"","teacher_note":"","student_support":""},{"text":"What makes a place feel comfortable to you?","levels":["A2","B1","B2"],"challenge":"","teacher_note":"","student_support":""},{"text":"What is one small decision that improved your daily life?","levels":["A2","B1","B2"],"challenge":"","teacher_note":"","student_support":""},{"text":"What is something people often misunderstand about your job or studies?","levels":["A2","B1","B2"],"challenge":"","teacher_note":"","student_support":""},{"text":"If you had one extra free hour every day, how would you use it?","levels":["A2","B1","B2"],"challenge":"","teacher_note":"","student_support":""},{"text":"Which skill is more useful than people think?","levels":["A2","B1","B2"],"challenge":"","teacher_note":"","student_support":""}],"summary":"Rapid speaking rounds: answer, extend, then ask a follow-up.","favorite":true,"variants":["Speed round: 20 seconds only.","Depth round: ask Why? three times.","No-safe-answer round: ban yes/no openings."],"group_size":"1–4","instructions":"Answer for at least 30 seconds. Add one detail that was not asked for. Finish by asking a related question back.","activity_type":"conversation","student_intro":null,"student_steps":[],"teacher_notes":null,"presenter_style":"prompt","useful_language":[],"duration_minutes":12},{"tags":["sales","argument"],"goals":["persuasion","fluency","functional language"],"title":"Convince Me","levels":["B1","B2","C1"],"status":"active","prompts":[{"text":"Convince me to wake up at 5:00 every day.","levels":["B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"Convince me that meetings are useful.","levels":["B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"Sell me a holiday in a place where it rains every day.","levels":["B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"Convince me to delete all social media for one month.","levels":["B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"Sell me a very expensive notebook with no special technology.","levels":["B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""}],"summary":"Lo studente deve venderti o difendere qualcosa di poco attraente usando argomenti sempre più forti.","favorite":true,"variants":["Business English: usa objection-handling chunks.","C1: dopo due minuti, cambia improvvisamente target audience.","Vocabulary: assegna tre chunks obbligatori da integrare."],"group_size":"1–3","instructions":"Dai un oggetto, un’idea o una posizione difficile da vendere. Tu opponi 2–3 obiezioni reali. Lo studente deve rispondere senza ripetere lo stesso argomento.","activity_type":"debate","student_intro":null,"student_steps":[],"teacher_notes":null,"presenter_style":"prompt","useful_language":[],"duration_minutes":15},{"tags":["debate","opinions"],"goals":["argumentation","hedging","spontaneous speaking"],"title":"Defend the Opposite","levels":["B1","B2","C1"],"status":"active","prompts":[{"text":"Working from home is better than working in an office.","levels":["B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"University is still the best route to a good career.","levels":["B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"People should answer work messages outside working hours.","levels":["B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"It is better to be extremely organised than spontaneous.","levels":["B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"Artificial intelligence makes people less creative.","levels":["B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""}],"summary":"Argue for the position you would not normally choose.","favorite":true,"variants":["Ban good, bad, better and worse.","Add a 30-second rebuttal.","Require one softener such as arguably or to some extent."],"group_size":"1–4","instructions":"Give your real opinion first. Then defend the opposite side for 60–90 seconds using at least two reasons and one example.","activity_type":"debate","student_intro":"First give your real opinion. Then switch sides and make the opposite position sound convincing.","student_steps":["State your real opinion briefly.","Defend the opposite view.","Give two reasons and one example.","Finish with a concession."],"teacher_notes":null,"presenter_style":"prompt","useful_language":["From another perspective…","One advantage is that…","That might be true, but…","A good example would be…","To some extent…"],"duration_minutes":15},{"tags":["taboo","retrieval"],"goals":["vocabulary","paraphrasing","fluency"],"title":"Explain It Without Saying It","levels":["A2","B1","B2","C1"],"status":"active","prompts":[{"text":"deadline | forbidden: time, finish, date","levels":["A2","B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"overwhelmed | forbidden: stress, busy, too much","levels":["A2","B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"run out of | forbidden: finish, none, empty","levels":["A2","B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"reschedule | forbidden: change, meeting, time","levels":["A2","B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"reliable | forbidden: trust, person, always","levels":["A2","B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""}],"summary":"Descrivi una parola o un chunk senza usare le parole vietate; l’altro deve indovinare.","favorite":false,"variants":["Per chunk: dopo l’indovinello, chiedi una collocation naturale.","A2: una sola parola vietata.","C1: richiedi definizione + esempio + contrasto con un termine simile."],"group_size":"1–6","instructions":"Scegli un target e 2–4 parole vietate. Chi descrive non può tradurre né mimare. Dopo che il target viene indovinato, deve essere usato in una frase personale o professionale.","activity_type":"vocabulary","student_intro":"Explain the target without saying the target itself or the forbidden words.","student_steps":["Describe the meaning.","Give an example or situation.","Keep talking until the other person guesses.","Use the target naturally after it is guessed."],"teacher_notes":null,"presenter_style":"taboo","useful_language":["It’s something you…","You use it when…","It’s similar to…, but…","For example…","The opposite would be…"],"duration_minutes":15},{"tags":["reformulation","real-life"],"goals":["natural English","chunks","register"],"title":"Make It Sound Like a Person","levels":["A2","B1","B2","C1"],"status":"active","prompts":[{"text":"I very like this place.","levels":["A2"],"challenge":"Say it in a more enthusiastic way too.","teacher_note":"Target: I really like / I love this place.","student_support":"Make it natural without changing the meaning."},{"text":"I am agree with you.","levels":["A2","B1"],"challenge":"Now disagree politely instead.","teacher_note":"Target: I agree with you.","student_support":"Keep the same meaning."},{"text":"I want to know if you received my email.","levels":["B1","B2"],"challenge":"Make it sound warmer, then more direct.","teacher_note":"Possible: I just wanted to check whether you received…","student_support":"Imagine this is a polite work follow-up."},{"text":"For me it is not a problem.","levels":["B1","B2"],"challenge":"Give one professional alternative.","teacher_note":"Depends on intent: That’s fine with me / I don’t mind / No problem on my end.","student_support":"Choose a natural phrase for a casual conversation."},{"text":"This solution is not convenient for us.","levels":["B2","C1"],"challenge":"Soften it without becoming vague.","teacher_note":"Possible: This option wouldn’t really work for us / may not be the best fit.","student_support":"Imagine a business negotiation."}],"summary":"Upgrade textbook English into something a real person would naturally say.","favorite":true,"variants":["Register ladder: casual → neutral → professional.","No translation round: explain why the original feels unnatural in English.","Chunk capture: save the best reformulation to the learner bank."],"group_size":"1–2","instructions":"Show a technically understandable but unnatural line. The learner makes it sound natural, then uses the upgraded version in context.","activity_type":"fluency","student_intro":"Make the sentence sound like something a real person would naturally say.","student_steps":["Read the original.","Say a more natural version.","Explain what changed.","Use it in a short conversation."],"teacher_notes":null,"presenter_style":"repair","useful_language":["A more natural way to say it is…","I’d probably say…","That sounds a little too…","In a work context, I’d use…"],"duration_minutes":15},{"tags":["low prep","conversation","chunks"],"goals":["fluency","vocabulary","justifying opinions"],"title":"Odd One Out — Conversation Edition","levels":["B1","B2","C1"],"status":"active","prompts":[{"text":"deadline · schedule · postpone · exhausted","levels":["B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"convincing · awkward · persuasive · believable","levels":["B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"bring up · point out · run into · mention","levels":["B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"budget · afford · expensive · negotiate","levels":["B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"apologise · admit · deny · confess","levels":["B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""}],"summary":"Quattro parole o idee: scegli l’intruso, ma la parte importante è difendere la scelta e contestare quella dell’altro.","favorite":true,"variants":["A2: usa categorie più concrete e dai una frase-starter: “I think ___ is different because…”","C1: richiedi una seconda interpretazione e una controargomentazione.","Vocabulary focus: dopo ogni set, fai creare una frase naturale con due elementi non scelti."],"group_size":"1–4","instructions":"Mostra un set alla volta. Lo studente sceglie l’intruso e deve giustificare la risposta con almeno due frasi. Se esistono più interpretazioni plausibili, sfruttale: chiedi “Could another answer work?” e fai difendere una seconda scelta.","activity_type":"speaking_game","student_intro":"Choose the odd one out. There may be more than one possible answer — the important part is how you justify your choice.","student_steps":["Choose one item.","Explain why it is different.","Listen to a challenge or alternative answer.","Defend your choice or change your mind."],"teacher_notes":"Evita set con una sola risposta puramente grammaticale: deve generare discussione.","presenter_style":"odd_one_out","useful_language":["I’d say ___ is the odd one out because…","The others all have something in common: …","Another possible answer could be…","I see your point, but…"],"duration_minutes":12},{"tags":["timed","warmup"],"goals":["fluency","confidence","extended answers"],"title":"One Minute, No Escape","levels":["A2","B1","B2","C1"],"status":"active","prompts":[{"text":"A habit you would like to change","levels":["A2","B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"Something people spend too much money on","levels":["A2","B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"A place you could happily visit again","levels":["A2","B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"A skill everybody should learn","levels":["A2","B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"A small thing that can ruin your day","levels":["A2","B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"Something you used to believe but changed your mind about","levels":["A2","B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""}],"summary":"Un minuto di parlato continuo su un tema semplice, con follow-up che impediscono risposte preparate.","favorite":true,"variants":["A2: 30 secondi e tre parole-guida.","B2/C1: vieta tre parole troppo facili prima di iniziare.","Second round: stesso tema, ma lo studente deve includere due nuovi chunks."],"group_size":"1–4","instructions":"Dai 15 secondi per pensare. Lo studente parla per 60 secondi senza fermarsi. Tu non correggi durante il minuto. Alla fine scegli solo 1–2 upgrade linguistici e fai un secondo mini-round di 30 secondi.","activity_type":"fluency","student_intro":null,"student_steps":[],"teacher_notes":"Perfetto come apertura lezione per misurare scioltezza senza farlo sembrare un test.","presenter_style":"prompt","useful_language":[],"duration_minutes":10},{"tags":["roleplay","real life"],"goals":["pragmatics","natural chunks","conversation repair"],"title":"Repair the Conversation","levels":["B1","B2","C1"],"status":"active","prompts":[{"text":"At work: “Give me the file today.”","levels":["B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"Small talk: “Why are you not married?”","levels":["B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"Restaurant: “I want another table because this is bad.”","levels":["B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"Meeting: “You are wrong.”","levels":["B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"Email follow-up: “Why didn’t you answer me?”","levels":["B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"Travel: “Tell me where the station is.”","levels":["B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""}],"summary":"Improve awkward lines, then continue the interaction naturally.","favorite":true,"variants":["Register shift: casual, neutral, professional.","Use one chunk from the learner’s Word & Chunk Bank.","Pressure mode: five seconds to repair the line."],"group_size":"1–2","instructions":"Read the awkward line. Explain what sounds wrong, blunt or unnatural. Replace it, say it aloud, then continue for at least three turns.","activity_type":"speaking_game","student_intro":"The sentence may sound too direct, awkward or unnatural. Make it better and keep the conversation going.","student_steps":["Read the original line.","Make it sound more natural.","Say your improved version aloud.","Continue the conversation for at least three turns."],"teacher_notes":null,"presenter_style":"repair","useful_language":["Would you mind…?","Could you possibly…?","I’m not sure I agree.","I was wondering if…","Sorry to bother you, but…"],"duration_minutes":18},{"tags":["sales","creative"],"goals":["persuasion","functional language","improvisation"],"title":"Sell Me Something Useless","levels":["B1","B2","C1"],"status":"active","prompts":[{"text":"Sell me a notebook that costs €80 and has no special technology.","levels":["B1","B2"],"challenge":"I say: “A normal notebook costs €3.”","teacher_note":"Push objection handling.","student_support":"Focus on design, durability, identity or experience."},{"text":"Sell a silent alarm clock to someone who sleeps very deeply.","levels":["B1","B2"],"challenge":"The customer is extremely sceptical.","teacher_note":"","student_support":"Invent a plausible benefit."},{"text":"Sell a one-day holiday package in your own city to a local resident.","levels":["B1","B2","C1"],"challenge":"They say they have already seen everything.","teacher_note":"Good for benefit framing.","student_support":"Create a new perspective on familiar places."},{"text":"Sell a premium pen to a company that has gone completely paperless.","levels":["B2","C1"],"challenge":"The buyer says the product contradicts company policy.","teacher_note":"C1: require reframing rather than feature listing.","student_support":"Find a symbolic, practical or social use."}],"summary":"Improvised persuasion with deliberately difficult products and audiences.","favorite":false,"variants":["Change the target audience halfway through.","Ban cheap adjectives like amazing and great.","Teacher raises one objection every 20 seconds."],"group_size":"1–4","instructions":"Give the learner a product and an audience. They have 60 seconds to make it sound worth buying.","activity_type":"debate","student_intro":"You have one minute to make an awkward product sound genuinely worth buying.","student_steps":["Understand the product and audience.","Choose the strongest benefit.","Make your pitch.","Handle the objection."],"teacher_notes":null,"presenter_style":"roleplay","useful_language":["What makes this different is…","The real benefit is…","I understand that concern, but…","This is designed for people who…"],"duration_minutes":15},{"tags":["improvisation"],"goals":["storytelling","past tenses","fluency"],"title":"Story Chain — But Something Changes","levels":["A2","B1","B2","C1"],"status":"active","prompts":[{"text":"You wake up in a hotel room and don’t remember how you got there.","levels":["A2","B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"A stranger gives you an envelope and says: “Don’t open it here.”","levels":["A2","B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"You miss your train, and that turns out to be the best thing that happened all week.","levels":["A2","B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"Your phone receives a photo taken five minutes in the future.","levels":["A2","B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""}],"summary":"Costruzione di una storia a turni con cambi improvvisi che costringono a reagire e collegare idee.","favorite":false,"variants":["Twists: “Someone is lying”, “The location suddenly changes”, “A phone call interrupts everything”, “One detail from the beginning becomes important”.","A2: usa solo past simple e sequencers.","B2+: richiedi almeno un flashback o una falsa pista."],"group_size":"1–6","instructions":"Iniziate con una frase. Ogni turno aggiunge 1–3 frasi. Ogni due turni pesca un cambiamento e incorporalo immediatamente senza ricominciare.","activity_type":"storytelling","student_intro":"Build the story together. Every new turn changes something, so listen carefully and adapt.","student_steps":["Continue the story for 2–4 sentences.","Keep the details already established.","Use the new twist.","At the end, retell the whole story in one minute."],"teacher_notes":null,"presenter_style":"story","useful_language":["At first…","While this was happening…","All of a sudden…","It turned out that…","In the end…"],"duration_minutes":15},{"tags":["information gap"],"goals":["questions","interaction","clarification"],"title":"The Missing Detail","levels":["A2","B1","B2"],"status":"active","prompts":[{"text":"I arrived at work this morning and everyone looked at me.","levels":["A2","B1","B2"],"challenge":"","teacher_note":"","student_support":""},{"text":"I bought something yesterday and immediately regretted it.","levels":["A2","B1","B2"],"challenge":"","teacher_note":"","student_support":""},{"text":"My friend cancelled our plans for a very strange reason.","levels":["A2","B1","B2"],"challenge":"","teacher_note":"","student_support":""},{"text":"I received an email that completely changed my week.","levels":["A2","B1","B2"],"challenge":"","teacher_note":"","student_support":""},{"text":"I was speaking English with someone and suddenly the conversation became much easier.","levels":["A2","B1","B2"],"challenge":"","teacher_note":"","student_support":""}],"summary":"Domande naturali per ricostruire una situazione incompleta invece di rispondere passivamente.","favorite":false,"variants":["A2: fornisci starters: Why…? What happened…? Had you…?","B2: imponi almeno due follow-up questions prima di fare una nuova topic question.","Teacher swap: lo studente inventa il mistero e tu fai le domande."],"group_size":"1–2","instructions":"Leggi solo la situazione iniziale. Lo studente deve scoprire cosa è successo facendo domande. Tu puoi rispondere solo alle domande poste: non regalare informazioni.","activity_type":"conversation","student_intro":null,"student_steps":[],"teacher_notes":"Ottimo per studenti che sanno rispondere ma fanno poche domande.","presenter_style":"prompt","useful_language":[],"duration_minutes":12},{"tags":["questions","reverse task"],"goals":["question formation","interaction","conversation skills"],"title":"The Missing Question","levels":["A1","A2","B1","B2"],"status":"active","prompts":[{"text":"ANSWER: About three times a week.","levels":["A1","A2"],"challenge":"Ask one follow-up question too.","teacher_note":"Possible: How often do you…? Many valid answers.","student_support":"Think: How often…?"},{"text":"ANSWER: Because I needed a change.","levels":["A2","B1"],"challenge":"Ask a question that makes this answer sound natural.","teacher_note":"Accept multiple contexts; focus on question grammar.","student_support":"Think about a past decision."},{"text":"ANSWER: I would, but only if I could work remotely.","levels":["B1","B2"],"challenge":"Ask a second question that explores the condition.","teacher_note":"Conditional question formation.","student_support":"Think about a hypothetical choice."},{"text":"ANSWER: Not exactly. It was more complicated than that.","levels":["B1","B2"],"challenge":"Create the original question and then continue the conversation.","teacher_note":"Good for repair and nuance.","student_support":"The previous question probably made an assumption."}],"summary":"Learners see an answer and must discover the most natural question that could have produced it.","favorite":true,"variants":["Give two possible questions for the same answer.","Teacher rejects the first question as unnatural; learner repairs it.","A1: provide the first question word."],"group_size":"1–4","instructions":"Show an answer. The learner invents the question, then asks one natural follow-up.","activity_type":"speaking_game","student_intro":"You get the answer first. Your job is to discover the question.","student_steps":["Read the answer.","Build a natural question.","Ask it aloud.","Add one follow-up."],"teacher_notes":null,"presenter_style":"prompt","useful_language":["How often…?","Why did…?","Would you…?","What made you…?","How did…?"],"duration_minutes":12},{"tags":["follow-up","small talk"],"goals":["interaction","questions","conversation skills"],"title":"Three Questions Deeper","levels":["A2","B1","B2","C1"],"status":"active","prompts":[{"text":"What did you do this weekend?","levels":["A2","B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"What are you working on at the moment?","levels":["A2","B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"What kind of places do you enjoy visiting?","levels":["A2","B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"What is something you are looking forward to?","levels":["A2","B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"What makes a workday feel productive for you?","levels":["A2","B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""}],"summary":"Qualunque risposta diventa conversazione: ogni risposta deve generare tre follow-up non ripetitivi.","favorite":false,"variants":["A2: mostra question stems: Why / How often / Who with / What happened next?","B2+: vieta di ripetere le stesse question words.","Reverse: lo studente conduce tutta la conversazione per tre minuti."],"group_size":"1–4","instructions":"Parti da una domanda comune. Dopo la risposta, l’interlocutore deve fare tre follow-up che vadano progressivamente più in profondità. Vietato cambiare subito argomento.","activity_type":"warmup","student_intro":null,"student_steps":[],"teacher_notes":null,"presenter_style":"prompt","useful_language":[],"duration_minutes":10},{"tags":["scaffolding","reformulation"],"goals":["extended answers","chunks","accuracy"],"title":"Upgrade That Answer","levels":["A2","B1","B2","C1"],"status":"active","prompts":[{"text":"I like travelling.","levels":["A2","B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"My job is stressful.","levels":["A2","B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"I think social media is bad.","levels":["A2","B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"I want to improve my English.","levels":["A2","B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"The meeting was difficult.","levels":["A2","B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""}],"summary":"Parti da una risposta piatta e trasformala in una risposta più naturale, precisa e personale.","favorite":true,"variants":["A2: usa schema answer + because + example.","B2+: aggiungi nuance o contrasto.","C1: cambia registro: casual → professional oppure neutral → persuasive."],"group_size":"1–3","instructions":"Mostra una risposta debole. Lo studente la migliora in tre passaggi: aggiungi dettaglio, aggiungi motivo/esempio, sostituisci almeno una parte con un chunk più naturale.","activity_type":"fluency","student_intro":null,"student_steps":[],"teacher_notes":"Molto utile quando lo studente dà risposte grammaticalmente corrette ma troppo povere.","presenter_style":"prompt","useful_language":[],"duration_minutes":15},{"tags":["creative","narration"],"goals":["storytelling","past tenses","inference"],"title":"What Happened Just Before?","levels":["A2","B1","B2"],"status":"active","prompts":[{"text":"You are standing outside a closed supermarket holding a birthday cake with your name on it.","levels":["A2","B1"],"challenge":"Add one surprising detail from ten minutes earlier.","teacher_note":"A2: scaffold past simple with first/then/after that.","student_support":"Who bought it? Why is the shop closed? Why are you there?"},{"text":"Your boss sends you a message saying: “Please do not explain this by email.”","levels":["B1","B2"],"challenge":"Include a misunderstanding.","teacher_note":"Good for reported speech and workplace chunks.","student_support":"What happened? What did you send? Why is email a problem?"},{"text":"You arrive home and there is a suitcase outside your door that is not yours.","levels":["A2","B1","B2"],"challenge":"The obvious explanation is wrong.","teacher_note":"","student_support":"Who could it belong to? How did it get there?"},{"text":"Everyone in the meeting suddenly becomes silent when you enter.","levels":["B1","B2"],"challenge":"Retell it from another person’s perspective.","teacher_note":"B2: push perspective and speculation.","student_support":"What were they talking about? Why does your arrival matter?"}],"summary":"Inference prompts that make learners build a plausible backstory from one strange moment.","favorite":false,"variants":["Reverse timeline: every new sentence moves further into the past.","Teacher adds one fact the learner must integrate.","Final retell: one-minute coherent story."],"group_size":"1–4","instructions":"Show the final scene only. The learner invents what happened immediately before it, then expands the story backwards.","activity_type":"storytelling","student_intro":"You only know the final moment. Build the story that led to it.","student_steps":["Study the scene.","Explain what happened just before.","Keep moving backwards.","Retell the full story in order."],"teacher_notes":null,"presenter_style":"story","useful_language":["Maybe…","It could have happened because…","Before that…","What probably happened was…"],"duration_minutes":15},{"tags":["zero prep","decision making"],"goals":["fluency","opinions","conditionals"],"title":"Would You Rather — No Easy Answers","levels":["A2","B1","B2","C1"],"status":"active","prompts":[{"text":"Would you rather have a job you love with an average salary, or a boring job that pays extremely well?","levels":["A2","B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"Would you rather always arrive 30 minutes early or 10 minutes late?","levels":["A2","B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"Would you rather live abroad for five years without your family or stay home and turn down your dream opportunity?","levels":["A2","B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"Would you rather be excellent at speaking English but weak at writing, or the opposite?","levels":["A2","B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""},{"text":"Would you rather work with a brilliant but difficult boss or a kind but disorganised one?","levels":["A2","B1","B2","C1"],"challenge":"","teacher_note":"","student_support":""}],"summary":"Scelte scomode o realistiche che obbligano a spiegare priorità, conseguenze e compromessi.","favorite":true,"variants":["A2: limita la risposta a choice + because + one example.","B2+: chiedi “What would make you switch sides?”","Work version: usa solo dilemmi professionali."],"group_size":"1–6","instructions":"Leggi una scelta. Lo studente deve scegliere subito, poi spiegare perché. Dopo la prima risposta aggiungi sempre una complicazione o chiedi cosa potrebbe fargli cambiare idea.","activity_type":"conversation","student_intro":"Choose one option. There is no perfect answer, so explain what matters most to you.","student_steps":["Make your choice.","Give at least two reasons.","React to one follow-up question.","Say what could make you change your mind."],"teacher_notes":null,"presenter_style":"choice","useful_language":["I’d rather… because…","The main reason is…","It would depend on…","I might change my mind if…"],"duration_minutes":15}]'::jsonb);

with seed as (
  select value as row
  from speaking_activity_seed, jsonb_array_elements(payload)
)
update public.admin_speaking_activities activity
set
  summary = seed.row ->> 'summary',
  activity_type = seed.row ->> 'activity_type',
  levels = array(select jsonb_array_elements_text(seed.row -> 'levels')),
  goals = array(select jsonb_array_elements_text(seed.row -> 'goals')),
  tags = array(select jsonb_array_elements_text(seed.row -> 'tags')),
  duration_minutes = nullif(seed.row ->> 'duration_minutes','')::integer,
  group_size = seed.row ->> 'group_size',
  instructions = coalesce(seed.row ->> 'instructions',''),
  prompts = coalesce(seed.row -> 'prompts','[]'::jsonb),
  variants = coalesce(seed.row -> 'variants','[]'::jsonb),
  teacher_notes = nullif(seed.row ->> 'teacher_notes',''),
  favorite = coalesce((seed.row ->> 'favorite')::boolean,false),
  status = coalesce(seed.row ->> 'status','active'),
  student_intro = seed.row ->> 'student_intro',
  student_steps = coalesce(seed.row -> 'student_steps','[]'::jsonb),
  useful_language = coalesce(seed.row -> 'useful_language','[]'::jsonb),
  presenter_style = coalesce(seed.row ->> 'presenter_style','prompt'),
  updated_at = now()
from seed
where lower(activity.title) = lower(seed.row ->> 'title');

with seed as (
  select value as row
  from speaking_activity_seed, jsonb_array_elements(payload)
)
insert into public.admin_speaking_activities (
  title, summary, activity_type, levels, goals, tags, duration_minutes, group_size,
  instructions, prompts, variants, teacher_notes, favorite, status,
  student_intro, student_steps, useful_language, presenter_style
)
select
  seed.row ->> 'title',
  seed.row ->> 'summary',
  seed.row ->> 'activity_type',
  array(select jsonb_array_elements_text(seed.row -> 'levels')),
  array(select jsonb_array_elements_text(seed.row -> 'goals')),
  array(select jsonb_array_elements_text(seed.row -> 'tags')),
  nullif(seed.row ->> 'duration_minutes','')::integer,
  seed.row ->> 'group_size',
  coalesce(seed.row ->> 'instructions',''),
  coalesce(seed.row -> 'prompts','[]'::jsonb),
  coalesce(seed.row -> 'variants','[]'::jsonb),
  nullif(seed.row ->> 'teacher_notes',''),
  coalesce((seed.row ->> 'favorite')::boolean,false),
  coalesce(seed.row ->> 'status','active'),
  seed.row ->> 'student_intro',
  coalesce(seed.row -> 'student_steps','[]'::jsonb),
  coalesce(seed.row -> 'useful_language','[]'::jsonb),
  coalesce(seed.row ->> 'presenter_style','prompt')
from seed
where not exists (
  select 1 from public.admin_speaking_activities existing
  where lower(existing.title) = lower(seed.row ->> 'title')
);

drop table if exists speaking_activity_seed;

notify pgrst, 'reload schema';
